/*
 * Demo data: three weeks of a simulated viewer, generated by feeding made-up impressions and
 * ratings through the *real* learning and stats code. Clearly flagged as demo in the report.
 * The simulated viewer has a planted wanting/liking gap so the report has something to show.
 */
(function (root) {
  "use strict";

  const HOOKED = [
    "You WON'T Believe What Happened Next...", "The Truth About Seed Oils Nobody Tells You",
    "This Streamer Got EXPOSED Live 😳😳😳", "STOP Doing This Before It's Too Late!!",
    "I Spent $100,000 On The World's Biggest Pizza", "Everyone Is Talking About This New Phone",
    "Why This Celebrity Is Finally Cancelled", "The Most Insane Plot Twist Of All Time",
    "Warning: Your Phone Is Doing This Right Now", "What They Found In The Basement...",
    "He DESTROYED Them In 30 Seconds", "Leaked Footage Before It's Deleted",
    "The Real Reason Your Diet Isn't Working", "This One Trick Changes Everything",
    "World's Hardest Challenge (IMPOSSIBLE)", "The Drama That Broke The Internet",
  ];
  const CALM = [
    "How Transformers Work, Explained Visually", "A Quiet Morning Hike in the Dolomites",
    "Cooking Dal Makhani From Scratch", "Lecture 4: Bayesian Inference", "Learning Jazz Piano: Week 12",
    "A Short History of the Printing Press", "Full Body Stretch for Beginners", "Building a Bookshelf by Hand",
    "Interview with a Marine Biologist", "Lo-fi Beats to Study To", "Why Bridges Don't Fall Down",
    "Exploring Old Tokyo Neighbourhoods", "Chess Endgames for Club Players", "Painting a Watercolour Sunset",
  ];
  const CHANNELS_HOOKED = ["ClickVortex", "DramaDaily", "Shock Lab", "TopTenTonight", "ViralVault"];
  const CHANNELS_CALM = ["3Blue Explainer", "Slow Travel", "Home Kitchen", "Open Lectures", "Workshop Notes"];
  // Hooky packaging, genuinely good videos: the case channel learning exists for.
  const GOOD_HOOKY = "Curious Science";
  const TRUE_CHANNEL_LIKE = { [GOOD_HOOKY]: 1.6 };
  const MOODS = ["calm", "good", "tired", "stressed"];

  // The simulated viewer's true (hidden) behaviour.
  const TRUE_WANT = { bias: -2.4, curiosity_gap: 0.9, outrage: 0.8, fear: 0.6, urgency: 0.5, social_proof: 0.4,
                      hype: 0.7, shouting: 0.5, loud_thumbnail: 0.5, late_night: 0.5, deep_session: 0.3 };
  const TRUE_LIKE = { bias: 0.9, curiosity_gap: -0.5, outrage: -0.6, fear: -0.4, urgency: -0.35, social_proof: -0.2,
                      hype: -0.35, shouting: -0.25, loud_thumbnail: -0.15, late_night: -0.6, deep_session: -0.6 };

  function rng(seed) {
    let s = seed >>> 0;
    return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
  }

  function generate(W, S) {
    const rand = rng(7);
    const pick = (a) => a[Math.floor(rand() * a.length)];
    const model = W.freshModel();
    const stats = S.freshStats();
    const watches = [];
    const prob = (w, x) => W.sigmoid(w.bias + W.FEATURES.reduce((z, f) => z + (w[f] || 0) * x[f], 0));

    const start = new Date(Date.now() - 21 * 86400000).setHours(0, 0, 0, 0);   // local midnight, so hours are real hours
    for (let day = 0; day < 21; day++) {
      const sessions = 1 + Math.floor(rand() * 3);
      for (let s = 0; s < sessions; s++) {
        const hour = pick([8, 12, 13, 17, 19, 20, 21, 22, 23, 23, 0, 1]);
        let t = start + day * 86400000 + hour * 3600000 + Math.floor(rand() * 1800000);
        const mood = pick(MOODS);
        let depth = 0;
        const length = 3 + Math.floor(rand() * (hour >= 23 || hour < 2 ? 22 : 10));
        for (let k = 0; k < length && t < Date.now(); k++) {
          // A screen of 8 recommendations; the viewer clicks at most one.
          const screen = Array.from({ length: 8 }, () => {
            const hooked = rand() < 0.45;
            const title = hooked ? pick(HOOKED) : pick(CALM);
            const hooks = W.detectHooks(title, hooked && rand() < 0.6 ? 0.8 : 0.2);
            const channel = hooked ? (rand() < 0.2 ? GOOD_HOOKY : pick(CHANNELS_HOOKED)) : pick(CHANNELS_CALM);
            return { id: Math.floor(rand() * 1e9).toString(36), title, channel, hooks, hooked };
          });
          const d = new Date(t);
          const ctx = { lateNight: W.isLateNight(d), depth };
          let chosen = null;
          for (const v of screen) {
            const x = W.features(v.hooks, ctx);
            const clicked = !chosen && rand() < prob(TRUE_WANT, x) * 2.2;
            if (clicked) chosen = v;
            W.update(model, "want", x, clicked ? 1 : 0, { channel: v.channel });
            for (const c of S.cellsFor(stats, v.hooks, d.getHours(), depth)) {
              c.shown++;
              if (clicked) c.clicked++;
            }
          }
          if (!chosen) {
            t += 60000;
            continue;
          }
          depth++;
          const x = W.features(chosen.hooks, { lateNight: ctx.lateNight, depth });
          const pLike = W.sigmoid(Math.log(prob(TRUE_LIKE, x) / (1 - prob(TRUE_LIKE, x))) + (TRUE_CHANNEL_LIKE[chosen.channel] || 0))
            - (mood === "stressed" ? 0.1 : 0) + (mood === "calm" ? 0.05 : 0);
          const rating = Math.max(1, Math.min(5, Math.round(1.4 + 4 * pLike + (rand() - 0.5) * 1.8)));
          const durationSec = 120 + Math.floor(rand() * 900);
          const watchedSec = Math.floor(durationSec * Math.min(1, pLike + rand() * 0.4));
          const w = { id: chosen.id, title: chosen.title, channel: chosen.channel,
                      hooks: chosen.hooks, ts: t, depth, watchedSec, durationSec, hour: d.getHours(),
                      lateNight: ctx.lateNight, rating: rand() < 0.8 ? rating : null, mood: null };
          if (w.rating != null) w.mood = rand() < 0.6 ? mood : null;
          watches.push(w);
          const cells = S.cellsFor(stats, w.hooks, w.hour, depth);
          for (const c of cells) c.watched++;
          if (w.rating != null) {
            if (w.mood) cells.push((stats.moods[w.mood] = stats.moods[w.mood] || { shown: 0, clicked: 0, watched: 0, rated: 0, ratingSum: 0, worth: 0 }));
            for (const c of cells) {
              c.rated++;
              c.ratingSum += w.rating;
              c.worth += w.rating >= 4 ? 1 : 0;
            }
            W.update(model, "like", x, W.ratingTarget(w.rating), { channel: w.channel });
          } else {
            const y = W.implicitTarget(watchedSec, durationSec);   // unrated: learn from how much was watched
            if (y != null) W.update(model, "like", x, y, { channel: w.channel, weight: 0.5 });
          }
          w.learned = true;
          t += (watchedSec + 20) * 1000;
        }
      }
    }
    W.rebuildRecord(model, watches);
    return { model, stats, watches };
  }

  root.WorthItDemo = { generate };
  if (typeof module !== "undefined" && module.exports) module.exports = root.WorthItDemo;
})(typeof globalThis !== "undefined" ? globalThis : this);
